-- =====================================================================
-- ROLLBACK de integración CORONELBOT
-- ADVERTENCIA: elimina la bitácora y metadatos de integración.
-- No elimina vales ni productos operativos ya creados.
-- Respaldar la base antes de ejecutar.
-- =====================================================================

SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;

DROP TABLE IF EXISTS rebanado_sync_runs;

SET @exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'vale_productos' AND INDEX_NAME = 'uq_vale_productos_external_line_key');
SET @sql := IF(@exists > 0, 'ALTER TABLE vale_productos DROP INDEX uq_vale_productos_external_line_key', 'SELECT ''Índice de línea ya no existe'' AS info'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'vale_productos' AND INDEX_NAME = 'idx_vale_productos_sap_line');
SET @sql := IF(@exists > 0, 'ALTER TABLE vale_productos DROP INDEX idx_vale_productos_sap_line', 'SELECT ''Índice SAP de línea ya no existe'' AS info'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'vale_productos' AND COLUMN_NAME = 'last_synced_at'); SET @sql := IF(@exists > 0, 'ALTER TABLE vale_productos DROP COLUMN last_synced_at', 'SELECT ''last_synced_at ya no existe'' AS info'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
