SET @exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'vale_productos' AND COLUMN_NAME = 'external_line_key'); SET @sql := IF(@exists > 0, 'ALTER TABLE vale_productos DROP COLUMN external_line_key', 'SELECT ''external_line_key ya no existe'' AS info'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'vale_productos' AND COLUMN_NAME = 'sap_line_num'); SET @sql := IF(@exists > 0, 'ALTER TABLE vale_productos DROP COLUMN sap_line_num', 'SELECT ''sap_line_num ya no existe'' AS info'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- Convierte tipos no estándar a Otro antes de restaurar el ENUM original.
UPDATE vale_productos SET tipo_rebanado = 'Otro' WHERE tipo_rebanado NOT IN ('Estándar','Grueso','Otro');
UPDATE vale_productos SET presentacion = LEFT(presentacion, 50) WHERE CHAR_LENGTH(presentacion) > 50;
ALTER TABLE vale_productos MODIFY COLUMN presentacion VARCHAR(50) NOT NULL;
ALTER TABLE vale_productos MODIFY COLUMN tipo_rebanado ENUM('Estándar','Grueso','Otro') NOT NULL DEFAULT 'Estándar';

